146	// ── Update types (all fields optional except primary key) ─────
147	
148	export type ProfileUpdate = Partial<
149	  Omit<ProfileRow, "id" | "created_at">
150	>;
151	
152	export type ScanUpdate = Partial<Omit<ScanRow, "id" | "user_id" | "created_at">>;
153	
154	export type ScanResultUpdate = Partial<
155	  Omit<ScanResultRow, "id" | "scan_id" | "pillar" | "created_at">
156	>;
