162	// ── Supabase Database generic type ────────────────────────────
163	
164	export interface Database {
165	  public: {
166	    Tables: {
167	      profiles: {
168	        Row: ProfileRow;
169	        Insert: ProfileInsert;
170	        Update: ProfileUpdate;
171	      };
172	      scans: {
173	        Row: ScanRow;
174	        Insert: ScanInsert;
175	        Update: ScanUpdate;
176	      };
177	      scan_results: {
178	        Row: ScanResultRow;
179	        Insert: ScanResultInsert;
180	        Update: ScanResultUpdate;
181	      };
182	      integrations: {
183	        Row: IntegrationRow;
184	        Insert: IntegrationInsert;
185	        Update: IntegrationUpdate;
186	      };
187	      audit_logs: {
188	        Row: AuditLogRow;
189	        Insert: AuditLogInsert;
190	        Update: Partial<Omit<AuditLogRow, "id" | "created_at">>;
191	      };
192	    };
193	    Views: Record<string, never>;
194	    Functions: {
195	      increment_scan_usage: {
196	        Args: { user_uuid: string };
197	        Returns: boolean;
198	      };
199	      reset_monthly_scans: {
200	        Args: Record<string, never>;
201	        Returns: void;
202	      };
203	      is_admin: {
204	        Args: Record<string, never>;
205	        Returns: boolean;
206	      };
207	    };
208	    Enums: Record<string, never>;
209	  };
210	}
211	
212	// ── Convenience helpers ───────────────────────────────────────
213	// Use these for typed Supabase client access.
214	
215	export type Tables<T extends keyof Database["public"]["Tables"]> =
216	  Database["public"]["Tables"][T]["Row"];
217	
218	export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
219	  Database["public"]["Tables"][T]["Insert"];
220	
221	export type TablesUpdate<T extends keyof Database["public"]["Tables"]> =
222	  Database["public"]["Tables"][T]["Update"];
223	
224	export type DbFunctions = Database["public"]["Functions"];
