1	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
2	import { toast } from "sonner";
3	import supabase from "@/lib/supabase";
4	import { useAuth } from "@/contexts/AuthContext";
5	import type { Scan, PageType } from "@/types";
6	import type { ScanRow } from "@/types/database";
7	
8	// ── Query keys ──────────────────────────────────────────────────
9	
10	export const scanKeys = {
11	  all: ["scans"] as const,
12	  lists: () => [...scanKeys.all, "list"] as const,
13	  list: (userId: string) => [...scanKeys.lists(), userId] as const,
14	  details: () => [...scanKeys.all, "detail"] as const,
15	  detail: (id: string) => [...scanKeys.details(), id] as const,
16	};
17	
18	// ── Row → App type mapper ───────────────────────────────────────
19	
20	function rowToScan(row: ScanRow): Scan {
21	  return {
22	    id: row.id,
23	    user_id: row.user_id,
24	    url: row.url,
25	    favicon_url: row.favicon_url,
26	    page_title: row.page_title,
27	    page_type: row.page_type,
28	    status: row.status,
29	    overall_score: row.overall_score,
30	    issues_found: row.issues_found,
31	    critical_issues: row.critical_issues,
32	    warnings: row.warnings,
33	    quick_wins: row.quick_wins,
34	    screenshot_url: row.screenshot_url,
35	    device: row.device,
36	    created_at: row.created_at,
37	    completed_at: row.completed_at,
38	  };
39	}
40	
41	// ── useScans ────────────────────────────────────────────────────
42	
43	export function useScans() {
44	  const { user } = useAuth();
45	
46	  return useQuery({
47	    queryKey: scanKeys.list(user?.id ?? ""),
48	    queryFn: async (): Promise<Scan[]> => {
49	      if (!user?.id) return [];
50	
51	      const { data, error } = await supabase
52	        .from("scans")
53	        .select("*")
54	        .eq("user_id", user.id)
55	        .order("created_at", { ascending: false });
56	
57	      if (error) throw new Error(error.message);
58	      return (data as ScanRow[]).map(rowToScan);
59	    },
60	    enabled: !!user?.id,
61	    staleTime: 1000 * 30, // 30 seconds
62	  });
63	}
64	
65	// ── useScan ─────────────────────────────────────────────────────
66	
67	export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
68	  const { user } = useAuth();
69	
70	  return useQuery({
71	    queryKey: scanKeys.detail(id ?? ""),
72	    queryFn: async (): Promise<Scan | null> => {
73	      if (!id || !user?.id) return null;
74	
75	      const { data, error } = await supabase
76	        .from("scans")
77	        .select("*")
78	        .eq("id", id)
79	        .eq("user_id", user.id)
80	        .single();
81	
82	      if (error) {
83	        if (error.code === "PGRST116") return null;
84	        throw new Error(error.message);
85	      }
86	
87	      return rowToScan(data as ScanRow);
88	    },
89	    enabled: !!id && !!user?.id,
90	    refetchInterval: options?.refetchInterval,
91	    staleTime: 0,
92	  });
93	}
94	
95	// ── useCreateScan ───────────────────────────────────────────────
96	
97	interface CreateScanInput {
98	  url: string;
99	  page_type: PageType;
100	}
101	
102	export function useCreateScan() {
103	  const { user, refreshProfile } = useAuth();
104	  const queryClient = useQueryClient();
105	
106	  return useMutation({
107	    mutationFn: async ({ url, page_type }: CreateScanInput): Promise<Scan> => {
108	      if (!user?.id) throw new Error("Not authenticated");
109	
110	      // Insert the scan row first
111	      const { data: scanData, error: insertError } = await supabase
112	        .from("scans")
113	        .insert({
114	          user_id: user.id,
115	          url,
116	          page_type,
117	          status: "pending" as const,
118	        })
119	        .select("*")
120	        .single();
121	
122	      if (insertError) throw new Error(insertError.message);
123	
124	      const scan = rowToScan(scanData as ScanRow);
125	
126	      // Invoke edge function — fire and don't block the return
127	      // The edge function updates the scan row when done
128	      supabase.functions
129	        .invoke("analyze-url", {
130	          body: { scan_id: scan.id, url, page_type },
131	        })
132	        .catch((err: unknown) => {
133	          console.error("Edge function invocation failed:", err);
134	          toast.error("Analysis engine failed to start. Please try re-scanning in a moment.", { duration: 6000 });
135	        });
136	
137	      return scan;
138	    },
139	    onSuccess: (data) => {
140	      if (!user?.id) return;
141	      // Optimistically prepend the new scan to the list cache
142	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
143	        prev ? [data, ...prev] : [data]
144	      );
145	      // Prime the detail cache
146	      queryClient.setQueryData(scanKeys.detail(data.id), data);
147	      // Refresh profile to show updated scans_used count
148	      refreshProfile();
149	    },
150	  });
151	}
152	
153	// ── useDeleteScan ───────────────────────────────────────────────
154	
155	export function useDeleteScan() {
156	  const { user } = useAuth();
157	  const queryClient = useQueryClient();
158	
159	  return useMutation({
160	    mutationFn: async (scanId: string): Promise<void> => {
161	      if (!user?.id) throw new Error("Not authenticated");
162	
163	      const { error } = await supabase
164	        .from("scans")
165	        .delete()
166	        .eq("id", scanId)
167	        .eq("user_id", user.id);
168	
169	      if (error) throw new Error(error.message);
170	    },
171	    onSuccess: (_data, scanId) => {
172	      if (!user?.id) return;
173	      // Remove from list cache
174	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
175	        prev ? prev.filter((s) => s.id !== scanId) : []
176	      );
177	      // Remove detail cache
178	      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
179	    },
180	  });
181	}
182	
183	// ── useRefreshScan ──────────────────────────────────────────────
184	// Creates a new scan for the same URL/page_type as an existing scan
185	
186	export function useRefreshScan() {
187	  const createScan = useCreateScan();
188	
189	  return useMutation({
190	    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
191	      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
192	    },
193	  });
194	}
