1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { PillarResult, Finding } from "@/types";
5	import type { ScanResultRow, DbFinding } from "@/types/database";
6	
7	// ── Query keys ──────────────────────────────────────────────────
8	
9	export const scanResultKeys = {
10	  all: ["scan-results"] as const,
11	  byScan: (scanId: string) => ["scan-results", scanId] as const,
12	};
13	
14	// ── Row → App type mapper ───────────────────────────────────────
15	
16	function dbFindingToFinding(f: DbFinding): Finding {
17	  return {
18	    id: f.id,
19	    title: f.title,
20	    severity: f.severity,
21	    current_state: f.current_state,
22	    recommendation: f.recommendation,
23	    ai_suggestion: f.ai_suggestion,
24	    is_premium: f.is_premium,
25	    effort: f.effort,
26	    estimated_lift: f.estimated_lift,
27	    category: f.category,
28	  };
29	}
30	
31	function rowToPillarResult(row: ScanResultRow): PillarResult {
32	  return {
33	    id: row.id,
34	    scan_id: row.scan_id,
35	    pillar: row.pillar,
36	    score: row.score,
37	    weight: row.weight,
38	    benchmark: row.benchmark,
39	    findings: (row.findings ?? []).map(dbFindingToFinding),
40	  };
41	}
42	
43	// ── useScanResults ──────────────────────────────────────────────
44	
45	export function useScanResults(scanId: string | undefined) {
46	  const { user } = useAuth();
47	
48	  return useQuery({
49	    queryKey: scanResultKeys.byScan(scanId ?? ""),
50	    queryFn: async (): Promise<PillarResult[]> => {
51	      if (!scanId || !user?.id) return [];
52	
53	      const { data, error } = await supabase
54	        .from("scan_results")
55	        .select("*")
56	        .eq("scan_id", scanId);
57	
58	      if (error) throw new Error(error.message);
59	      return (data as ScanResultRow[]).map(rowToPillarResult);
60	    },
61	    enabled: !!scanId && !!user?.id,
62	    staleTime: 1000 * 60 * 5, // 5 minutes — results don't change after a scan completes
63	  });
64	}
