1012	  } catch (_e) {
1013	    console.error("Failed to parse vision AI response:", rawText.slice(0, 500));
1014	    // Return safe defaults
1015	    return buildDefaultVisionResult();
1016	  }
1017	
1018	  return {
1019	    visual_hierarchy: sanitizePillarResult(
1020	      parsed.visual_hierarchy as Record<string, unknown>,
1021	      "vh",
1022	    ),
1023	    cta_effectiveness: sanitizePillarResult(
1024	      parsed.cta_effectiveness as Record<string, unknown>,
1025	      "ct",
1026	    ),
1027	    trust_signals: sanitizePillarResult(
1028	      parsed.trust_signals as Record<string, unknown>,
1029	      "ts",
1030	    ),
