1038	function parseAndSanitizeTextResult(rawText: string): TextAnalysisResult {
1039	  let parsed: Record<string, unknown>;
1040	  try {
1041	    parsed = JSON.parse(extractJsonFromText(rawText));
1042	  } catch (_e) {
1043	    console.error("Failed to parse text AI response:", rawText.slice(0, 500));
1044	    return buildDefaultTextResult();
1045	  }
1046	
1047	  return {
1048	    value_proposition: sanitizePillarResult(
1049	      parsed.value_proposition as Record<string, unknown>,
1050	      "vp",
1051	    ),
1052	    content_copy: sanitizePillarResult(
1053	      parsed.content_copy as Record<string, unknown>,
1054	      "cc",
1055	    ),
1056	    cta_effectiveness: parsed.cta_effectiveness
1057	      ? sanitizePillarResult(
1058	          parsed.cta_effectiveness as Record<string, unknown>,
1059	          "ct_copy",
1060	        )
1061	      : undefined,
