1088	  const defaultPillar = { score: 50, findings: [] };
1089	  return {
1090	    visual_hierarchy: defaultPillar,
1091	    cta_effectiveness: defaultPillar,
1092	    trust_signals: defaultPillar,
1093	    mobile_experience: defaultPillar,
1094	  };
1095	}
