const BRAND_PRIMARY = "#5B5FC7";

import { motion } from "framer-motion";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
} from "recharts";
import { TrendingUp } from "lucide-react";
import { EmptyState } from "@/components/shared/EmptyState";
import { ChartErrorBoundary } from "@/components/shared/ChartErrorBoundary";

// ── Date formatting helper (no external library) ─────────────────

const MONTH_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function formatChartDate(dateStr: string): string {
  const d = new Date(dateStr);
  return `${MONTH_ABBR[d.getMonth()]} ${d.getDate()}`;
}

// ── Types ────────────────────────────────────────────────────────

export interface ScoreHistoryPoint {
  date: string;  // ISO date string
  score: number;
}

interface ScoreHistoryChartProps {
  data: ScoreHistoryPoint[];
  height?: number;
}

// ── Custom Tooltip ────────────────────────────────────────────────

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{ value: number }>;
  label?: string;
}

function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
  if (!active || !payload?.length) return null;
  return (
    <div
      style={{
        fontSize: 12,
        borderRadius: 8,
        border: "1px solid hsl(220 13% 91%)",
        boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
        background: "#fff",
        padding: "8px 12px",
      }}
    >
      <p style={{ fontWeight: 600, marginBottom: 2 }}>{label ? formatChartDate(label) : ""}</p>
      <p style={{ color: BRAND_PRIMARY }}>{payload[0].value}/100</p>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────

export function ScoreHistoryChart({ data, height = 200 }: ScoreHistoryChartProps) {
  const hasData = data.length >= 2;

  if (!hasData) {
    return (
      <div style={{ height }}>
        <EmptyState
          icon={TrendingUp}
          title="Not enough data yet"
          description="Run more scans to see your score trend."
          className="py-0 h-full flex items-center justify-center"
        />
      </div>
    );
  }

  // Map to include formatted label while keeping original date for tooltip
  const chartData = data.map((d) => ({
    date: d.date,
    label: formatChartDate(d.date),
    score: d.score,
  }));

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4, ease: "easeOut" }}
    >
      <ChartErrorBoundary fallbackHeight={height}>
        <ResponsiveContainer width="100%" height={height}>
          <AreaChart
            data={chartData}
            margin={{ top: 8, right: 8, bottom: 0, left: -20 }}
          >
            <defs>
              <linearGradient id="scoreHistoryFill" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={BRAND_PRIMARY} stopOpacity={0.18} />
                <stop offset="100%" stopColor={BRAND_PRIMARY} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis
              dataKey="label"
              tick={{ fontSize: 10, fill: "#94A3B8" }}
              axisLine={false}
              tickLine={false}
              interval="preserveStartEnd"
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 10, fill: "#94A3B8" }}
              axisLine={false}
              tickLine={false}
              tickCount={5}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine
              y={70}
              stroke="#22C55E"
              strokeDasharray="4 4"
              strokeWidth={1}
              label={{
                value: "Good",
                position: "insideTopRight",
                fontSize: 10,
                fill: "#22C55E",
              }}
            />
            <Area
              type="monotone"
              dataKey="score"
              stroke={BRAND_PRIMARY}
              strokeWidth={2}
              fill="url(#scoreHistoryFill)"
              dot={{ r: 3, fill: BRAND_PRIMARY, strokeWidth: 0 }}
              activeDot={{ r: 5, fill: BRAND_PRIMARY, strokeWidth: 2, stroke: "#fff" }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </ChartErrorBoundary>
    </motion.div>
  );
}

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { TrendingUp, TrendingDown, ChevronDown, ChevronUp } from "lucide-react";
import { cn } from "@/lib/utils";
import { useCountUp } from "@/hooks/use-count-up";
import type { ScanComparison } from "@/hooks/use-scan-comparison";

// ── Animated Score Number ─────────────────────────────────────────

function AnimatedScore({ value }: { value: number }) {
  const animated = useCountUp(value, 800);
  return <span>{animated}</span>;
}

// ── Props ─────────────────────────────────────────────────────────

interface ScoreComparisonBannerProps {
  comparison: ScanComparison;
}

// ── Pillar label map ──────────────────────────────────────────────

const PILLAR_LABELS: Record<string, string> = {
  value_proposition: "Value Prop",
  cta_effectiveness: "CTA",
  trust_signals: "Trust",
  visual_hierarchy: "Visual",
  mobile_experience: "Mobile",
  content_copy: "Content",
  page_performance: "Performance",
};

// ── Main Component ────────────────────────────────────────────────

export function ScoreComparisonBanner({ comparison }: ScoreComparisonBannerProps) {
  const [expanded, setExpanded] = useState(false);

  if (!comparison.hasPrevious) return null;

  const isImprovement = comparison.scoreDelta >= 0;
  const deltaAbs = Math.abs(comparison.scoreDelta);

  return (
    <motion.div
      initial={{ opacity: 0, y: -8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, ease: "easeOut" }}
      className={cn(
        "rounded-xl border px-5 py-4",
        isImprovement
          ? "border-green-200 bg-green-50"
          : "border-red-200 bg-red-50"
      )}
    >
      {/* Top row — summary */}
      <button
        type="button"
        className="flex w-full items-center justify-between gap-3"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
      >
        <div className="flex flex-wrap items-center gap-3">
          <div
            className={cn(
              "flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm font-semibold",
              isImprovement ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"
            )}
          >
            {isImprovement ? (
              <TrendingUp className="h-4 w-4" />
            ) : (
              <TrendingDown className="h-4 w-4" />
            )}
            Score changed
          </div>

          <div className="flex items-center gap-2 text-sm text-slate-700">
            <span className="text-base font-bold text-slate-800">
              <AnimatedScore value={comparison.previousScore} />
            </span>
            <span className="text-muted-foreground">→</span>
            <span className="text-base font-bold text-slate-800">
              <AnimatedScore value={comparison.currentScore} />
            </span>
            <span
              className={cn(
                "inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-bold",
                isImprovement
                  ? "bg-green-200 text-green-800"
                  : "bg-red-200 text-red-800"
              )}
            >
              {isImprovement ? "+" : "-"}{deltaAbs} pts
            </span>
          </div>

          <span className="hidden text-xs text-muted-foreground sm:block">
            vs. previous scan
          </span>
        </div>

        <div className="shrink-0 text-muted-foreground">
          {expanded ? (
            <ChevronUp className="h-4 w-4" />
          ) : (
            <ChevronDown className="h-4 w-4" />
          )}
        </div>
      </button>

      {/* Expanded pillar deltas */}
      <AnimatePresence>
        {expanded && comparison.pillarDeltas.length > 0 && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="overflow-hidden"
          >
            <div className="mt-4 border-t border-black/5 pt-4">
              <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Pillar changes
              </p>
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-7">
                {comparison.pillarDeltas.map(({ pillar, previous, current, delta }) => {
                  const isUp = delta >= 0;
                  return (
                    <div
                      key={pillar}
                      className="flex flex-col items-center rounded-lg border border-black/5 bg-white/60 px-2 py-2.5 text-center"
                    >
                      <span className="mb-1 text-2xs font-medium text-muted-foreground leading-tight">
                        {PILLAR_LABELS[pillar] ?? pillar}
                      </span>
                      <span className="text-sm font-bold text-slate-800">
                        {previous} → {current}
                      </span>
                      <span
                        className={cn(
                          "mt-1 text-xs font-semibold",
                          delta === 0
                            ? "text-muted-foreground"
                            : isUp
                            ? "text-green-600"
                            : "text-red-500"
                        )}
                      >
                        {delta === 0 ? "—" : isUp ? `+${delta}` : `${delta}`}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

