  label?: string;
}

function CustomTooltip({ active, payload, label }: TooltipProps) {
  if (!active || !payload?.length) return null;
  return (
    <div
      style={{
        fontSize: 12,
        borderRadius: 8,
        border: "1px solid hsl(220 13% 91%)",
        boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
        background: "#fff",
        padding: "8px 12px",
      }}
    >
      <p style={{ fontWeight: 600, marginBottom: 4 }}>{label}</p>
      {payload.map((entry) => (
        <p key={entry.name} style={{ color: entry.name === "previous" ? GRAY_PREVIOUS : BRAND_PRIMARY }}>
          {entry.name === "previous" ? "Previous" : "Current"}: {entry.value}
        </p>
      ))}
    </div>
  );
}

// ── Delta label ───────────────────────────────────────────────────

interface DeltaBadgeProps {
  delta: number;
}

function DeltaBadge({ delta }: DeltaBadgeProps) {
  if (delta === 0) return null;
  const isPos = delta > 0;
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full px-1.5 py-0 text-2xs font-bold",
        isPos ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
      )}
    >
      {isPos ? `+${delta}` : delta}
    </span>
  );
}

// ── Props ─────────────────────────────────────────────────────────

interface PillarComparisonViewProps {
  pillarDeltas: PillarDelta[];
}

// ── Main Component ────────────────────────────────────────────────

export function PillarComparisonView({ pillarDeltas }: PillarComparisonViewProps) {
  if (pillarDeltas.length === 0) return null;

  const chartData = pillarDeltas.map((d) => ({
    pillar: PILLAR_SHORT[d.pillar] ?? d.pillar,
    previous: d.previous,
    current: d.current,
    delta: d.delta,
  }));

  return (
    <div>
      {/* Legend */}
      <div className="mb-3 flex items-center gap-4 text-xs text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: GRAY_PREVIOUS }} />
          Previous
        </span>
        <span className="flex items-center gap-1.5">
          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: BRAND_PRIMARY }} />
          Current
        </span>
      </div>

      <ChartErrorBoundary fallbackHeight={200}>
        <ResponsiveContainer width="100%" height={200}>
          <BarChart
            data={chartData}
            margin={{ top: 16, right: 8, bottom: 0, left: -20 }}
            barCategoryGap="30%"
            barGap={2}
          >
            <XAxis
              dataKey="pillar"
              tick={{ fontSize: 10, fill: "#94A3B8" }}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 10, fill: "#94A3B8" }}
              axisLine={false}
              tickLine={false}
              tickCount={5}
            />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="previous" name="previous" radius={[3, 3, 0, 0]} maxBarSize={28}>
              {chartData.map((_, i) => (
                <Cell key={i} fill={GRAY_PREVIOUS} />
              ))}
              <LabelList dataKey="previous" position="top" style={{ fontSize: 9, fill: "#94A3B8" }} />
            </Bar>
            <Bar dataKey="current" name="current" radius={[3, 3, 0, 0]} maxBarSize={28}>
              {chartData.map((_, i) => (
                <Cell key={i} fill={BRAND_PRIMARY} />
              ))}
              <LabelList dataKey="current" position="top" style={{ fontSize: 9, fill: BRAND_PRIMARY }} />
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </ChartErrorBoundary>

      {/* Delta badges row */}
      <div className="mt-3 flex flex-wrap justify-around gap-2">
        {pillarDeltas.map((d) => (
          <div key={d.pillar} className="flex flex-col items-center gap-0.5">
            <span className="text-2xs text-muted-foreground">{PILLAR_SHORT[d.pillar] ?? d.pillar}</span>
            <DeltaBadge delta={d.delta} />
          </div>
        ))}
      </div>
    </div>
  );
}

