import { useNavigate } from "react-router-dom";
import { TrendingUp, TrendingDown, Minus, History, ScanLine } from "lucide-react";
import { motion } from "framer-motion";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { PageTransition } from "@/components/shared/PageTransition";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { ScoreHistoryChart } from "@/components/audit/ScoreHistoryChart";
import { useAllUrlHistory } from "@/hooks/use-scan-history";
import type { UrlHistoryGroup } from "@/hooks/use-scan-history";
import { cn } from "@/lib/utils";

// ── URL truncation ────────────────────────────────────────────────

function truncateUrl(url: string, max = 48): string {
  try {
    const u = new URL(url);
    const display = u.hostname + u.pathname;
    return display.length > max ? display.slice(0, max) + "…" : display;
  } catch {
    return url.length > max ? url.slice(0, max) + "…" : url;
  }
}

// ── Delta Badge ───────────────────────────────────────────────────

function DeltaChip({ delta }: { delta: number }) {
  if (delta === 0) {
    return (
      <span className="inline-flex items-center gap-0.5 rounded-full bg-muted px-2 py-0.5 text-xs font-semibold text-muted-foreground">
        <Minus className="h-3 w-3" />
        No change
      </span>
    );
  }
  const isUp = delta > 0;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-bold",
        isUp ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
      )}
    >
      {isUp ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
      {isUp ? `+${delta}` : delta} pts
    </span>
  );
}

// ── URL History Card ──────────────────────────────────────────────

function UrlHistoryCard({ group, index }: { group: UrlHistoryGroup; index: number }) {
  const navigate = useNavigate();

  const sparklineData = group.entries.map((e) => ({
    date: e.scanned_at,
    score: e.score,
  }));

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: "easeOut", delay: index * 0.06 }}
    >
      <Card
        className="cursor-pointer border-border/40 shadow-soft transition-all duration-150 hover:border-primary/30 hover:shadow-md"
        onClick={() => navigate(`/reports/${group.latestScanId}`)}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            navigate(`/reports/${group.latestScanId}`);
          }
        }}
        aria-label={`View history for ${group.url}`}
      >
        <CardContent className="p-5">
          <div className="flex items-start gap-4">
            {/* Score ring */}
            <div className="shrink-0">
              <ScoreRing score={group.latestScore} size={56} strokeWidth={5} showLabel={false} />
            </div>

            {/* Main info */}
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {truncateUrl(group.url)}
                  </p>
                  <p className="mt-0.5 text-xs text-muted-foreground">
                    {group.entries.length} scan{group.entries.length !== 1 ? "s" : ""}
                  </p>
                </div>
                <DeltaChip delta={group.delta} />
              </div>

              {/* Sparkline */}
              <div className="mt-3">
                <ScoreHistoryChart data={sparklineData} height={60} />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ── Loading Skeleton ──────────────────────────────────────────────

function HistorySkeleton() {
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
      {[1, 2, 3, 4].map((i) => (
        <Skeleton key={i} className="h-40 w-full rounded-xl" />
      ))}
    </div>
  );
}

// ── Empty State ───────────────────────────────────────────────────

function HistoryEmptyState() {
  const navigate = useNavigate();
  return (
    <div className="flex flex-col items-center justify-center py-24 text-center">
      <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-muted/50">
        <History className="h-8 w-8 text-muted-foreground" />
      </div>
      <h3 className="text-lg font-semibold text-foreground">No history yet</h3>
      <p className="mt-2 max-w-sm text-sm text-muted-foreground">
        You haven't scanned any URLs yet. Run your first scan to start tracking scores over time.
      </p>
      <Button className="mt-6" onClick={() => navigate("/scan")}>
        <ScanLine className="mr-2 h-4 w-4" />
        Run First Scan
      </Button>
    </div>
  );
}

// ── Page ──────────────────────────────────────────────────────────

const ScoreHistory = () => {
  const { data: groups = [], isLoading } = useAllUrlHistory();

  return (
    <PageTransition>
      <div className="space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
            Score History
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Track how your CRO scores have changed over time for each URL.
          </p>
        </div>

        {/* Content */}
        {isLoading ? (
          <HistorySkeleton />
        ) : groups.length === 0 ? (
          <HistoryEmptyState />
        ) : (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {groups.map((group, i) => (
              <UrlHistoryCard key={group.url_hash} group={group} index={i} />
            ))}
          </div>
        )}
      </div>
    </PageTransition>
  );
};

export default ScoreHistory;

